import { createClient } from "@supabase/supabase-js";

const url = process.env.SUPABASE_URL!;

export const supabase = createClient(url, process.env.SUPABASE_ANON_KEY!);

export const supabaseAdmin = createClient(url, process.env.SUPABASE_SERVICE_ROLE_KEY!, {
  auth: { autoRefreshToken: false, persistSession: false },
});

export async function query<T = unknown>(table: string, filters?: Record<string, unknown>) {
  let q = supabaseAdmin.from(table).select("*");
  if (filters) {
    for (const [key, value] of Object.entries(filters)) {
      q = q.eq(key, value as string);
    }
  }
  const { data, error } = await q;
  if (error) throw error;
  return data as T[];
}
